def comp_counts(grid):
    out={}
    for color in {c for row in grid for c in row if c!=7}:
        pts={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==color};left=set(pts);n=0
        while left:
            n+=1;stack=[left.pop()]
            while stack:
                r,c=stack.pop();near={(rr,cc) for rr,cc in left if abs(rr-r)<=1 and abs(cc-c)<=1};left-=near;stack.extend(near)
        out[color]=(n,len(pts))
    return out
